Следующий код на C++ читает текстовый файл построчно и подсчитывает количество вхождений определенного слова в файл:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string word; // Слово для поиска
    cout << "Enter the word to search: ";
    cin >> word;

    string filename;
    cout << "Enter the file name: ";
    cin >> filename;

    int count = 0; // Счетчик вхождений слова
    ifstream file(filename); // Открываем файл на чтение

    if (!file) { // Проверяем, что файл открыт успешно
        cerr << "Error: Cannot open file " << filename << endl;
        return 1;
    }

    string line;
    while (getline(file, line)) { // Читаем файл построчно
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) { // Находим все вхождения слова в строке
            count++; // Увеличиваем счетчик вхождений
            pos++; // Переходим на следующее вхождение
        }
    }

    file.close(); // Закрываем файл

    cout << "Number of occurrences of \"" << word << "\" in file " << filename << " is: " << count << endl;

    return 0;
}
```

В данном коде пользователю необходимо ввести слово для поиска и имя файла, после чего программа считывает файл построчно и находит все вхождения слова в каждой строке. Счетчик вхождений слова обновляется на каждом найденном вхождении. После завершения чтения файла, программа выводит общее количество вхождений слова в файл. 

